```go
type Config struct {
  Value  string `json:"a"`
  Raw    json.RawMessage `json:"b"`
}
```

To correctly decode `json.RawMessage` attributes, I use as recommended:
```go
cfg := Config{}
err := yaml.UnmarshalWithOptions(data, &cfg, yaml.UseJSONUnmarshaler() )
```

If an attribute inside Raw contains escaped unicode characters, decode will fail.

Workaround: convert JSON to YAML, then call `yaml.UnmarshalWithOptions`.

**To Reproduce**

https://go.dev/play/p/A8x5JcG_0F_o

```go
package main

import (
	"encoding/json"
	"fmt"

	"github.com/goccy/go-yaml"
)

var (
	data = `
{ 
  "a": "hello\u0026world",
  "b": {
    "c": "hello\u0026world"
  }
}`
)

type Config struct {
	Value string          `json:"a"`
	Raw   json.RawMessage `json:"b"`
}

func convert_to_yaml_good() {
	cfg := Config{}
	jsonData, _ := yaml.JSONToYAML([]byte(data))
	err := yaml.UnmarshalWithOptions(jsonData, &cfg, yaml.UseJSONUnmarshaler())
	if err != nil {
		fmt.Println(err.Error())
	} else {
		fmt.Printf("Decode successful: value: %v raw: %v\n", cfg.Value, string(cfg.Raw))
	}
}

func use_json_bad() {
	cfg := Config{}
	err := yaml.UnmarshalWithOptions([]byte(data), &cfg, yaml.UseJSONUnmarshaler())
	if err != nil {
		fmt.Println(err.Error())
	}

}

func main() {
	use_json_bad()
	convert_to_yaml_good()
}
```
