I've given this problem some more thought and realized that, since we're currently passing an interface to the Validator option, you can implement a custom validator struct to store the original validation errors if needed. For example:

```go
type User struct {
	FirstName string `validate:"required"`
	Email     string `validate:"required,email"`
	Age       int    `validate:"gte=0"`
}

type StructValidator struct {
	validator *validator.Validate
	err       error
}

func (sv *StructValidator) Struct(i interface{}) error {
	if err := sv.validator.Struct(i); err != nil {
		sv.err = err
		return err
	}

	return nil
}

func TestTranslate(t *testing.T) {
	validate := validator.New()

	jaLocale := ja.New()
	uni := ut.New(jaLocale, jaLocale)
	trans, found := uni.GetTranslator("ja")
	if !found {
		t.Fatalf("failed to get translator for ja locale")
	}

	if err := jaTranslations.RegisterDefaultTranslations(validate, trans); err != nil {
		t.Fatalf("failed to register translations: %v", err)
	}

	sv := &StructValidator{validator: validate}
	data := []byte(`
firstName: ""
email: "not-an-email"
age: -1
`)
	var user User
	err := yaml.UnmarshalWithOptions(data, &user, yaml.Validator(sv))
	if err != nil {
		if sv.err != nil {
			var fieldErrs validator.ValidationErrors
			ok := errors.As(sv.err, &fieldErrs)
			if !ok {
				t.Fatalf("failed to assert error type: %v", sv.err)
			}
			for _, fieldErr := range fieldErrs {
				fmt.Println(fieldErr.Translate(trans))
			}
			return
		}
		t.Fatalf("failed to unmarshal: %v", err)
	}
	t.Fatalf("expected validation error, got nil")
}
```

Since we haven’t received many requests related to accessing validation errors, and because there are workarounds like the above, we’re unlikely to add a dedicated option for this at the moment. However, if we start seeing more demand in the future, we should definitely revisit the issue.

