func redent(doc string, indent int) (string, error) {
	cm := make(yaml.CommentMap)
	var v interface{}
	err := yaml.NewDecoder(strings.NewReader(doc), yaml.CommentToMap(cm)).Decode(&v)
	if err != nil {
