	}
	var buf strings.Builder
	err = yaml.NewEncoder(&buf,
		yaml.WithComment(cm),
		yaml.Indent(indent),
		yaml.IndentSequence(true),
	).Encode(v)
	if err != nil {
		return "", err
	}
	return buf.String(), nil
