FWIW this can be done without special support by implementing the ByteUnmarshaler interface.  This code is for JSON but could be ported to yaml pretty easily:

```golang
type metadata struct {
 
        Tags []string
 
       Extra map[string]string
       Aux map[string]interface{}
}

func (m *metadata) UnmarshalJSON(b []byte) error {
       tmp := map[string]interface{}{}

       if err := json.Unmarshal(b, &tmp); err != nil {
               return err
       }

       if t, ok := tmp["title"]; ok {
               m.Title = t.(string)
               delete(tmp, "title")
       }

       if t, ok := tmp["raw"]; ok {
               m.Raw = t.(bool)
               delete(tmp, "raw")
       }

       if t, ok := tmp["tags"]; ok {
               tl := t.([]interface{})

               m.Tags = make([]string, len(tl))
               for i := range tl {
                       m.Tags[i] = tl[i].(string)
               }
               delete(tmp, "tags")
       }

       m.Aux = tmp

       return nil
}
